async (state, model) => {
  const taskType = state.taskType.toLowerCase();
  let skillName = '';

  if (taskType.includes('excel') || taskType.includes('spreadsheet')) {
    skillName = 'excel_operations';
  } else if (taskType.includes('word') || taskType.includes('document')) {
    skillName = 'word_operations';
  } else if (taskType.includes('pdf')) {
    skillName = 'pdf_processing';
  }

  const prompt = `Process the following task:
Task Type: ${state.taskType}
Input File: ${state.inputFile}
Output File: ${state.outputFile}

Use the ${skillName} skill to complete this task.`;

  const result = await model.invoke([{ role: 'user', content: prompt }]);

  return {
    processingSteps: [`${skillName} executed for ${state.taskType}`],
    messages: [{ role: 'assistant', content: result.content.toString() }]
  };
}
